  import Toaster from "./components/ui/Toast/Toaster";
  import { toast } from "./components/ui/Toast/toast";

  const showDefaultToast = () => toast.add({ title: "Event created", description: "Monday, Jan 5 at 4:00pm", autoClose: false });

  const showSuccessToast = () => toast.add({ title: "Saved successfully", type: "success", autoClose: false });

  const showErrorToast = () => toast.add({ title: "Something went wrong", type: "error", autoClose: false });

  const showWarningToast = () => toast.add({ title: "Low disk space", type: "warning", autoClose: false });

